/**
 * HaloPSA Node - Version 1
 * Discriminator: resource=site, operation=create
 */


interface Credentials {
  haloPSAApi: CredentialReference;
}

/** Create a client */
export type HaloPSAV1SiteCreateParams = {
  resource: 'site';
  operation: 'create';
/**
 * Enter site name
 */
    siteName: string | Expression<string>;
/**
 * Whether client can be selected by ID
 * @default false
 */
    selectOption?: boolean | Expression<boolean>;
/**
 * Client ID
 * @displayOptions.show { selectOption: [true] }
 */
    clientId: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Main Contact
     */
    maincontact_name?: string | Expression<string>;
    /** Notes
     */
    notes?: string | Expression<string>;
    /** Phone Number
     */
    phonenumber?: string | Expression<string>;
  };
};

export type HaloPSAV1SiteCreateNode = {
  type: 'n8n-nodes-base.haloPSA';
  version: 1;
  config: NodeConfig<HaloPSAV1SiteCreateParams> & { credentials?: Credentials };
};